import{_ as t,o as a,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const q=JSON.parse('{"title":"第 4 章 快速完成第一个真实任务（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第4章 快速完成第一个真实任务（易懂版）.md","filePath":"easy/第4章 快速完成第一个真实任务（易懂版）.md"}'),l={name:"easy/第4章 快速完成第一个真实任务（易懂版）.md"};function i(n,o,s,u,d,h){return a(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="第-4-章-快速完成第一个真实任务-易懂版" tabindex="-1">第 4 章 快速完成第一个真实任务（易懂版） <a class="header-anchor" href="#第-4-章-快速完成第一个真实任务-易懂版" aria-label="Permalink to &quot;第 4 章 快速完成第一个真实任务（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 4 章 快速完成第一个真实任务（完整版）](../../bluebook/第一篇 使用手册：先把我用起来/第 4 章 快速完成第一个真实任务.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>别再拿&quot;测试任务&quot;练手了——直接找一个真实的小活，跑通第一个完整闭环。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>学游泳不能只在岸上比划。找一个<strong>浅水区的小目标</strong>（比如&quot;帮我把 3 个文件合并成一个&quot;），游一个来回——呛几口水没关系，关键是<strong>完整游完</strong>。</p><h2 id="核心就-4-步-执行闭环" tabindex="-1">核心就 4 步（执行闭环） <a class="header-anchor" href="#核心就-4-步-执行闭环" aria-label="Permalink to &quot;核心就 4 步（执行闭环）&quot;">​</a></h2><ol><li><strong>说清楚</strong>：用上一章的四要素，把任务讲明白；</li><li><strong>等确认</strong>：我复述我的理解，你点头，我再动手；</li><li><strong>看过程</strong>：我一步步干活，你可以随时看进度、喊停；</li><li><strong>验结果</strong>：拿到成果后<strong>自己检查一遍</strong>，确认没问题才算完成。</li></ol><h2 id="怎么挑-第一个任务" tabindex="-1">怎么挑&quot;第一个任务&quot;？ <a class="header-anchor" href="#怎么挑-第一个任务" aria-label="Permalink to &quot;怎么挑&quot;第一个任务&quot;？&quot;">​</a></h2><ul><li>✅ 小的：10 分钟内能干完的；</li><li>✅ 真实的：是你工作中真需要的；</li><li>✅ 低风险的：搞砸了也没损失（比如合并文档，不是删数据库）；</li><li>✅ 有明确&quot;做完&quot;标准的：看到什么样子就算成了，你心里有数。</li></ul><h2 id="任务档案-做完留个-作业本" tabindex="-1">任务档案：做完留个&quot;作业本&quot; <a class="header-anchor" href="#任务档案-做完留个-作业本" aria-label="Permalink to &quot;任务档案：做完留个&quot;作业本&quot;&quot;">​</a></h2><p>每完成一个任务，花 1 分钟记三行：</p><ul><li><strong>任务</strong>：当时要干啥；</li><li><strong>指令</strong>：我用的原话（下次直接复制）；</li><li><strong>复盘</strong>：哪句没说清、哪步可优化。</li></ul><p>攒几个以后，你就有了自己的&quot;任务档案库&quot;——越用越顺。</p><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;把 <code>周报</code> 文件夹里 3 个 <code>.md</code> 文件，按文件名顺序合并成一个 <code>本周汇总.md</code>，放到 <code>交付</code> 文件夹。&quot;</p><p><strong>你会看到</strong>：我复述理解 → 合并 → 展示结果 → 你检查 → 完工 ✅</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 第一个任务就搞&quot;全自动大工程&quot;——<strong>先跑通小的</strong>；</li><li>❌ 交给 AI 就不管了——<strong>结果一定要自己验</strong>；</li><li>❌ 做完不记录——<strong>不留档案，下次还得从头说</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>找个真实小活，跑完&quot;说清→确认→执行→验收&quot;四步，记进任务档案。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>现在就挑一个任务：它小吗？真实吗？搞砸了没事吗？有明确完成标准吗？<strong>四个&quot;是&quot;就开工。</strong></p><p>👉 [下一章：加载一个真正用得上的 Skill（易懂版）](第5章 加载一个真正用得上的 Skill（易懂版）.md)</p>',23)])])}const _=t(l,[["render",i]]);export{q as __pageData,_ as default};
